 */
public class NinePatchDrawable extends BaseDrawable implements TransformDrawable {
  private NinePatch patch;

  /**
   * Creates an uninitialized NinePatchDrawable. The ninepatch must be {@link #setPatch(NinePatch)
   * set} before use.
   */
  public NinePatchDrawable() {
    // Initialize with a default, empty NinePatch to satisfy NullAway; users should call setPatch.
    this.patch = new NinePatch(new TextureRegion());
  }

  public NinePatchDrawable(NinePatch patch) {
    setPatch(patch);
  }

  public NinePatchDrawable(NinePatchDrawable drawable) {
    super(drawable);
    this.patch = drawable.patch;
  }

  public void draw(Batch batch, float x, float y, float width, float height) {
    patch.draw(batch, x, y, width, height);
  }

  public void draw(
      Batch batch,
      float x,
      float y,
      float originX,
      float originY,
      float width,
      float height,
      float scaleX,
      float scaleY,
      float rotation) {
    patch.draw(batch, x, y, originX, originY, width, height, scaleX, scaleY, rotation);
  }

  /**
   * Sets this drawable's ninepatch and set the min width, min height, top height, right width,
   * bottom height, and left width to the patch's padding.
   */
  public void setPatch(NinePatch patch) {
    this.patch = patch;
    setMinWidth(patch.getTotalWidth());
    setMinHeight(patch.getTotalHeight());
    setTopHeight(patch.getPadTop());
    setRightWidth(patch.getPadRight());
    setBottomHeight(patch.getPadBottom());
    setLeftWidth(patch.getPadLeft());
  }

  public NinePatch getPatch() {
    return patch;
  }

  /** Creates a new drawable that renders the same as this drawable tinted the specified color. */
  public NinePatchDrawable tint(Color tint) {
    NinePatchDrawable drawable = new NinePatchDrawable(this);
    drawable.patch = new NinePatch(drawable.getPatch(), tint);
    return drawable;
  }
}
